  test "a workflow's steps, compensations and updates run by activity name; an unknown one is not retried" do
    bypass = Bypass.open()
    test_pid = self()
    polls = TestGateway.counter()
    step = fn input, job -> {:ok, %{"got" => input, "kind" => job.kind}} end
    undo = fn input, _job -> {:ok, input} end

    shop =
      JoobQ.Workflow.new("shop")
      |> JoobQ.Workflow.step("reserve", step, input: %{"sku" => JoobQ.Workflow.input("sku")})
      |> JoobQ.Workflow.step("charge", step, compensate: JoobQ.Workflow.compensation(undo))
      |> JoobQ.Workflow.update("rename", step)

    tasks = [
      %{task("s", %{"sku" => "A1"}, "shop/reserve") | "kind" => "activity"},
      Map.merge(task("c", %{}, "shop/charge/compensate"), %{
        "kind" => "compensation",
        "checkpoints" => %{"charge" => 9}
      }),
      %{task("u", %{"to" => "x"}, "shop/@update/rename") | "kind" => "update"},
      %{task("n", %{}, "shop/nope") | "kind" => "activity"}
    ]

    TestGateway.stub(bypass, "POST", "/api/v1/sdk/tasks/poll", fn conn ->
      {body, conn} = TestGateway.read_json(conn)
      send(test_pid, {:poll, body})
      answer = if TestGateway.tick(polls) == 0, do: tasks, else: []
      if answer == [], do: Process.sleep(100)
      Plug.Conn.resp(conn, 200, Jason.encode!(%{tasks: answer}))
    end)

    TestGateway.stub(bypass, "POST", "/api/v1/sdk/tasks/ack", fn conn ->
      {body, conn} = TestGateway.read_json(conn)
      send(test_pid, {:ack, body["items"]})
      Plug.Conn.resp(conn, 200, ~s({"results":[]}))
    end)

    TestGateway.start_worker(bypass, workflows: [shop], except: [:poll])

    assert_receive {:poll, %{"task_queues" => ["mail", "workflows"]}}, 1_000
    items = collect_acks([], 4)
    assert items["s"]["output"] == %{"got" => %{"sku" => "A1"}, "kind" => "activity"}
    assert items["c"]["output"] == 9
    assert items["u"]["output"] == %{"got" => %{"to" => "x"}, "kind" => "update"}
    assert %{"error_class" => "JoobQ.UnknownActivity", "retryable" => false} = items["n"]
  end

